void main() async {
  final statefulIsolate = StatefulIsolate();
  print(await statefulIsolate.compute(_isPrime, 7));
  statefulIsolate.dispose();
}

bool _isPrime(int value) {
  if (value == 1) {
    return false;
  }
  for (int i = 2; i < value; ++i) {
    if (value % i == 0) {
      return false;
    }
  }
  return true;
}
